// Consulta o pedido (mock) e decide se escala ANTES de gastar tokens com RAG.
const PEDIDOS = {"PED-1001": {"status": "entregue", "valor": 48.9, "minutos_atraso": 35, "horas_desde_entrega": 5, "pagamento": "cartao"}, "PED-1002": {"status": "entregue", "valor": 72.0, "minutos_atraso": 0, "horas_desde_entrega": 3, "pagamento": "pix"}, "PED-1003": {"status": "entregue", "valor": 39.5, "minutos_atraso": 0, "horas_desde_entrega": 6, "pagamento": "saldo"}, "PED-1004": {"status": "em_rota", "valor": 55.0, "minutos_atraso": 25, "horas_desde_entrega": 0, "pagamento": "cartao"}, "PED-1005": {"status": "em_rota", "valor": 31.0, "minutos_atraso": 5, "horas_desde_entrega": 0, "pagamento": "pix"}, "PED-1006": {"status": "entregue", "valor": 120.0, "minutos_atraso": 0, "horas_desde_entrega": 60, "pagamento": "cartao"}, "PED-1008": {"status": "aguardando_restaurante", "valor": 45.0, "minutos_atraso": 0, "horas_desde_entrega": 0, "pagamento": "pix"}, "PED-1009": {"status": "cancelado", "valor": 58.0, "minutos_atraso": 0, "horas_desde_entrega": 0, "pagamento": "cartao"}, "PED-1010": {"status": "entregue", "valor": 89.9, "minutos_atraso": 0, "horas_desde_entrega": 4, "pagamento": "cartao"}, "PED-1011": {"status": "entregue", "valor": 27.0, "minutos_atraso": 0, "horas_desde_entrega": 2, "pagamento": "pix"}, "PED-1012": {"status": "entregue", "valor": 66.0, "minutos_atraso": 80, "horas_desde_entrega": 20, "pagamento": "cartao"}, "PED-1013": {"status": "entregue", "valor": 52.0, "minutos_atraso": 0, "horas_desde_entrega": 1, "pagamento": "cartao"}};
const base = $('Normalizar').first().json;
const cls = $input.first().json.output;

const pedido = base.pedido_id ? (PEDIDOS[base.pedido_id] || null) : null;
const dados_pedido = pedido ? {
  ...pedido,
  atraso_acima_tolerancia: pedido.minutos_atraso > 15,
  dentro_prazo_reembolso: pedido.horas_desde_entrega <= 48,
  acima_limite_reembolso_auto: pedido.valor > 60,
} : null;

let motivo = null;
if (cls.contem_injection) motivo = 'tentativa de injeção de prompt (KB-16)';
else if (cls.gatilho_escalonamento) motivo = 'gatilho de escalonamento obrigatório (KB-16)';
else if (cls.categoria === 'outro') motivo = 'fora do escopo do agente';
else if (cls.confianca < 0.7) motivo = 'confiança baixa na classificação';
else if (['atraso_entrega', 'reembolso'].includes(cls.categoria) && !pedido) motivo = 'pedido não identificado';

return [{ json: { ...base, classificacao: cls, dados_pedido, escalar_pre: !!motivo, motivo_escalonamento: motivo } }];

// Escalonamento antecipado (sem RAG, sem geração).
const p = $input.first().json;
const tokIn = Math.round((p.mensagem.length + 1800) / 4);
const custo = (tokIn * 0.15 + 120 * 0.60) / 1e6;
return [{ json: {
  ticket_id: p.ticket_id,
  decisao: 'escalado',
  categoria_prevista: p.classificacao.categoria,
  confianca: p.classificacao.confianca,
  motivo_escalonamento: p.motivo_escalonamento,
  resposta_ao_cliente: 'Seu caso foi encaminhado para um atendente humano, que dará continuidade em breve.',
  resumo_para_humano: p.classificacao.resumo,
  docs_recuperados: [],
  docs_citados: [],
  tokens_estimados: tokIn + 120,
  custo_estimado_usd: Number(custo.toFixed(6)),
} }];

// Junta os trechos recuperados em um único contexto.
const prev = $('Consultar pedido e decidir rota').first().json;
const docs = $input.all().map(i => (i.json.document && i.json.document.pageContent) || '').filter(Boolean);
const ids = [...new Set(docs.map(d => (d.match(/KB-\d+/) || [])[0]).filter(Boolean))];
return [{ json: { ...prev, contexto: docs.join('\n\n---\n\n'), docs_recuperados: ids } }];

