// Guardrail pós-geração + métricas estimadas.
// ATENÇÃO: tokens e custo são ESTIMATIVAS (caracteres/4). Ajuste os preços para o modelo que você usar.
const PRECO_IN_POR_MTOK = 0.15, PRECO_OUT_POR_MTOK = 0.60;
const prev = $('Montar contexto').first().json;
const out = $input.first().json.output;
let motivo = null;

const citados = out.docs_citados || [];
const invalidos = citados.filter(c => !prev.docs_recuperados.includes(c));
if (!out.resolvido) motivo = out.motivo_nao_resolvido || 'agente não conseguiu resolver';
else if (citados.length === 0) motivo = 'resposta sem citação de política';
else if (invalidos.length) motivo = 'citou documento que não foi recuperado: ' + invalidos.join(', ');
else if (prev.classificacao.categoria === 'reembolso' && prev.dados_pedido && prev.dados_pedido.dentro_prazo_reembolso && prev.dados_pedido.acima_limite_reembolso_auto) motivo = 'reembolso acima do limite automático (KB-04): aprovação humana';
else if (/ignore|ignorar|prompt do sistema|system prompt/i.test(out.resposta)) motivo = 'resposta suspeita';

const tokIn = Math.round((prev.mensagem.length + 1800 + prev.contexto.length + 1500) / 4);
const tokOut = Math.round(((out.resposta || '').length + 400) / 4);
const custo = (tokIn * PRECO_IN_POR_MTOK + tokOut * PRECO_OUT_POR_MTOK) / 1e6;

const escalado = !!motivo;
return [{ json: {
  ticket_id: prev.ticket_id,
  decisao: escalado ? 'escalado' : 'auto_resolvido',
  categoria_prevista: prev.classificacao.categoria,
  confianca: prev.classificacao.confianca,
  motivo_escalonamento: motivo,
  resposta_ao_cliente: escalado ? 'Seu caso foi encaminhado para um atendente humano, que dará continuidade em breve.' : out.resposta,
  resumo_para_humano: escalado ? prev.classificacao.resumo : null,
  docs_recuperados: prev.docs_recuperados,
  docs_citados: citados,
  tokens_estimados: tokIn + tokOut,
  custo_estimado_usd: Number(custo.toFixed(6)),
} }];
